mapper.select:
SELECT

FROM tbl_Complaint


        AND ComplainantID = #{complainantId,jdbcType=CHAR}


        AND ComplaintTargetID = #{complaintTargetId,jdbcType=CHAR}


        AND ComplaintType = #{complaintType,jdbcType=NVARCHAR}


        AND ProcessingStatus = #{processingStatus,jdbcType=NVARCHAR}


        AND HandlerAdminID = #{handlerAdminId,jdbcType=CHAR}


ORDER BY ComplaintTime DESC
